1	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
2	import type { SsrRes } from './types';
3	
4	type PaymentMethodImage = {
5	  src?: string;
6	  [key: string]: unknown;
7	};
8	
9	type PaymentMethodType = {
10	  images?: PaymentMethodImage[];
11	  [key: string]: unknown;
12	};
13	
14	type PaymentMethodData = {
15	  paymentMethodTypes?: Record<string, PaymentMethodType>;
16	  [key: string]: unknown;
17	};
18	
19	function transformIconPaths(data: PaymentMethodData, ecomServerHost: string): PaymentMethodData {
20	  const baseUrl = `https://${ecomServerHost}/on/demandware.static/Sites-Site/-/-/internal`;
21	  const methodTypes = data?.paymentMethodTypes;
22	  if (methodTypes) {
23	    for (const method of Object.values(methodTypes)) {
24	      for (const image of method.images ?? []) {
25	        if (image.src?.startsWith('/icons/')) {
26	          image.src = `${baseUrl}${image.src}`;
27	        }
28	      }
29	    }
30	  }
31	  return data;
32	}
33	
34	type SfPaymentsConfig = {
35	  sfPayments: { metadataUrl: string };
36	};
37	
38	/** Express handler for GET /api/payment-metadata — fetches and transforms Adyen payment method metadata. */
39	export async function paymentMetadataHandler(_req: unknown, res: SsrRes): Promise<void> {
40	  try {
41	    const { app } = getConfig() as { app: SfPaymentsConfig };
42	    const response = await fetch(app.sfPayments.metadataUrl, {
43	      headers: { Accept: 'application/json' },
44	    });
45	    if (!response.ok) {
46	      throw new Error(`Metadata request failed with status: ${response.status}`);
47	    }
48	    const data = (await response.json()) as PaymentMethodData;
49	    const transformedData = transformIconPaths(data, new URL(app.sfPayments.metadataUrl).hostname);
50	    res.setHeader('Content-Type', 'application/json');
51	    res.json(transformedData);
52	  } catch (error) {
53	    res.status(500).json({
54	      error: 'Failed to fetch metadata',
55	      details: (error as Error).message,
56	    });
57	  }
58	}
