1	import React from 'react';
2	import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import { ContentfulLivePreview } from '@contentful/live-preview';
4	import type { ContentfulAsset } from '../../types/contentful';
5	
6	type VideoEmbedProps = {
7	  videoEmbed: ContentfulAsset;
8	  entryId?: string;
9	  locale?: string;
10	};
11	
12	export const VideoEmbed = ({ videoEmbed, entryId, locale = 'en-US' }: VideoEmbedProps) => {
13	  if (!videoEmbed?.fields?.file?.url) {
14	    console.error('VideoEmbed: Missing required data', videoEmbed);
15	    return null;
16	  }
17	
18	  const { fields } = videoEmbed;
19	  const videoUrl = `https:${fields.file.url}`;
20	  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'videoEmbed', locale }) : {};
21	
22	  return (
23	    <Box padding={8} maxWidth="container.xl" marginX="auto" {...inspectorProps}>
24	      <Box as="video" width="full" controls poster={fields.description}>
25	        <source src={videoUrl} type={fields.file.contentType} />
26	        Your browser does not support the video tag.
27	      </Box>
28	    </Box>
29	  );
30	};
